import { useEffect } from 'react';
import { amount } from '../../shared/src/amount';
export function Amount({ value, onValue }: { value: string; onValue: (value: string) => void }) {
  useEffect(() => { onValue(value); }, [value, onValue]);
  return <div>{amount(value)}</div>;
}

